def transform(grid):
    """Complete cyclic row sequences or diagonal bands from sparse clues."""
    h, w = len(grid), len(grid[0])

    # Uniform rows encode a one-dimensional cyclic sequence; the number of
    # observed nonzero rows gives its cycle length.
    if all(len(set(row)) == 1 for row in grid):
        known = [(r, row[0]) for r, row in enumerate(grid) if row[0] != 0]
        if not known:
            return [row[:] for row in grid]
        period = len(known)
        pattern = {}
        for r, color in known:
            phase = r % period
            if phase in pattern and pattern[phase] != color:
                raise ValueError("inconsistent cyclic row clues")
            pattern[phase] = color
        if len(pattern) != period:
            raise ValueError("incomplete cyclic row clues")
        return [[pattern[r % period]] * w for r in range(h)]

    # Otherwise, the clues form diagonal bands repeated modulo a period.
    for period in range(1, max(h, w) + 1):
        pattern = {}
        valid = True
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == 0:
                    continue
                phase = (c - r) % period
                if phase in pattern and pattern[phase] != color:
                    valid = False
                    break
                pattern[phase] = color
            if not valid:
                break
        if valid and len(pattern) == period:
            return [[pattern[(c - r) % period] for c in range(w)] for r in range(h)]
    raise ValueError("could not infer a complete diagonal cycle")

